var n={title:`Teorie`,intro:`Krátká vysvětlení toho, jak trénink funguje: co která myšlenka znamená, jak ji využít a čemu se vyhnout. Každá teorie má krátkou a podrobnou verzi.`,disclaimer:`Tyto teorie jsou obecné vzdělávací informace, ne lékařská rada. Pokud máte bolest, zranění nebo zdravotní potíže, před úpravou tréninku se poraďte s lékařem nebo fyzioterapeutem.`,searchLabel:`Hledat v teoriích`,searchPlaceholder:`Hledat podle názvu nebo myšlenky`,topicLabel:`Téma`,allTopics:`Všechna témata`,count:`{shown} z {n} teorií`,empty:`Vašemu hledání neodpovídá žádná teorie.`,reset:`Zobrazit všechny teorie`,short:`Ve zkratce`,readMore:`Číst více`,readLess:`Zobrazit méně`,sources:`Zdroje`,previous:`Předchozí`,next:`Další`,backToList:`Všechny teorie`,inTopic:`Více v tématu {title}`,notFound:`Tato teorie nebyla nalezena.`};var t={foundations:`Základy tréninku`,body:`Tělo a pohyb`,variables:`Tréninkové proměnné`,patterns:`Pohybové vzorce`,programming:`Tvorba programu`,equipment:`Vybavení`,space:`Prostor a prostředí`,conditioning:`Kondice`,mobility:`Rozcvička a mobilita`,recovery:`Regenerace`,safety:`Bezpečnost a omezení`,groups:`Specifické skupiny`,progress:`Sledování pokroku`,myths:`Mýty`};var a={"1":{title:`Jak trénink mění tělo`,short:`Trénink je řízená zátěž, která nutí váš nervový systém, svaly, srdce a další tkáně zlepšovat se v úkolech, které opakujete. Pokrok vzniká spojením této zátěže s dostatečnou regenerací a postupným zvyšováním nároků, ne tím, že z každého tréninku uděláte vyčerpávající zkoušku.`},"2":{title:`Složky tělesné kondice`,short:`Tělesná kondice se skládá z několika částečně nezávislých schopností: síly, výbušnosti, svalové vytrvalosti, aerobní vytrvalosti, mobility, rovnováhy a koordinace. Když je znáte, snáze vyberete cviky odpovídající vašemu cíli, protože různé tréninky rozvíjejí různé věci.`},"3":{title:`Tréninkové cíle: celková kondice, síla, vytrvalost`,short:`Celková kondice, síla a vytrvalost jsou různé priority a každá ovlivňuje výběr cviků, úsilí, odpočinek i postup. Můžete rozvíjet několik vlastností zároveň, ale jeden hlavní cíl usnadňuje sestavení programu i posouzení jeho výsledků.`},"4":{title:`Úrovně kondice: začátečník, pokročilý, expert`,short:`Vaše tréninková úroveň popisuje zkušenosti a dovednosti s cviky a zátěžemi, které opravdu děláte, ne to, jak sportovně vypadáte. Začátečníci obvykle postupují s jednoduchým cvičením a mírným objemem, zatímco zkušenější cvičenci často potřebují promyšlenější plánování.`},"5":{title:`Kontrola připravenosti: kdy se nejdřív poradit s odborníkem`,short:`Kontrola připravenosti odhalí zdravotní obavy nebo příznaky, které mohou vyžadovat odbornou radu dříve, než začnete cvičit intenzivněji. Pomáhá vám rozhodovat se o tréninku bezpečněji, ale není to lékařská diagnóza a automaticky vám pohyb nezakazuje.`},"6":{title:`Doporučení pro pohybovou aktivitu`,short:`Doporučení pro pohybovou aktivitu stanovují minimální týdenní aktivitu spojenou s významnými zdravotními přínosy. Pro většinu dospělých je užitečným cílem pravidelná aerobní aktivita střední nebo vysoké intenzity plus silový trénink hlavních svalových skupin alespoň ve dvou dnech v týdnu.`},"7":{title:`Stanovení realistických tréninkových cílů`,short:`Užitečný tréninkový cíl je konkrétní, měřitelný, reálný a vázaný na časový rámec. Spojte požadovaný výsledek s týdenními kroky, které máte ve své moci, abyste viděli pokrok, i když se výsledky dostavují pomalu.`},"8":{title:`Pravidelnost a tréninkové návyky`,short:`Pravidelnost znamená trénovat dostatečně často a dostatečně dlouho na to, aby se zlepšení sčítala, i v nedokonalých týdnech. Krátké tréninky, které zvládnete opakovat, a předvídatelná rutina obvykle porazí ambiciózní plán, který po pár trénincích opustíte.`},"9":{title:`Hlavní svalové skupiny`,short:`Vaše hlavní svalové skupiny spolupracují při pohybu a stabilizaci těla, takže jejich trénink znamená víc než izolování jednotlivých svalů. Když víte, co která skupina dělá, snáze sestavíte vyvážené tréninky a pochopíte, proč jeden pohyb může zapojit několik oblastí najednou.`},"10":{title:`Jak svaly pracují: koncentricky, excentricky, izometricky`,short:`Svaly vytvářejí sílu nebo se jí brání při zkracování, protahování nebo držení polohy. Tyto koncentrické, excentrické a izometrické činnosti se často odehrávají v rámci jednoho cviku a pomáhají vysvětlit, co znamená ovládat váhu.`},"11":{title:`Typy svalových vláken`,short:`Kosterní svaly obsahují vlákna, která se liší odolností proti únavě a produkcí síly, obvykle se popisují jako typ I a typ II. Oba typy vám pomáhají při pohybu a trénink zlepšuje jejich výkon, aniž by z vás udělal úplně jiný „typ vlákna“.`},"12":{title:`Klouby a rozsah pohybu`,short:`Klouby se pohybují v rozsazích daných anatomií, svalovou kontrolou, pohyblivostí a pohodlím. Trénink v užitečném rozsahu, který ovládáte, obvykle buduje schopnosti s lepším přenosem než nucení všech do stejných poloh.`},"13":{title:`Páteř, střed těla a zpevnění`,short:`Vaše páteř vás nese a umožňuje pohyb a svaly trupu kolem ní pomáhají ovládat síly působící při cvičení. Zpevnění je koordinované napnutí trupu, které může zlepšit stabilitu, a není to totéž jako držet jednu strnulou polohu při každé činnosti.`},"14":{title:`Energetické systémy při cvičení`,short:`Při cvičení se využívají tři překrývající se energetické systémy: fosfagenní, glykolytický a oxidační. Všechny tři pracují neustále, ale jejich význam se mění podle toho, jak intenzivně a jak dlouho se pohybujete a kolik odpočíváte mezi výkony.`},"15":{title:`Tepová frekvence a tréninkové zóny`,short:`Tepová frekvence vám může pomoci odhadnout, jak náročné je aerobní cvičení, ale tréninkové zóny jsou jen přiblížení, ne univerzální biologické hranice. Pulz používejte spolu s dechem, testem řeči, vnímaným úsilím a svými zdravotními okolnostmi, abyste zvolili intenzitu, kterou udržíte.`},"16":{title:`Dýchání při cvičení`,short:`Dýchání podporuje pohyb, pomáhá regulovat tlak v trupu a mění se podle toho, jak tvrdě pracujete. Pro většinu začátečníků je praktickým způsobem, jak nezadržovat dech, když to není potřeba, stálý rytmus a výdech při náročnější části každého opakování.`},"17":{title:`Motorické učení: jak se buduje technika`,short:`Technika cviků je dovednost, kterou budujete opakovaným, pozorným cvičením a užitečnou zpětnou vazbou. Cviky se naučíte efektivněji, když začnete jednoduššími verzemi, budete opakování provádět konzistentně a ztížíte je až poté, co je ovládnete.`},"18":{title:`Růst svalů (hypertrofie)`,short:`Svalová hypertrofie je zvětšení svalů, které vzniká opakovaným tréninkem a regenerací. Mechanické zatížení je hlavním podnětem a trénink, objem, úsilí, dostatek výživy a spánku ovlivňují, jak moc se dokážete přizpůsobit.`},"19":{title:`Série, opakování a pauzy`,short:`Opakování je jeden pohyb cviku, série je skupina opakování a pauzy oddělují série nebo cviky. Společně určují, kolik práce se vejde do tréninku a jak dobře udržíte sílu, techniku nebo vytrvalost.`},"20":{title:`Rozsahy opakování a co trénují`,short:`Rozsahy opakování naznačují, na co se zaměřujete, ale netřídí trénink do přísných kategorií. Těžší práce s málo opakováními je nejdůležitější pro maximální sílu, svaly mohou růst v mnoha rozsazích a vysoký počet opakování může budovat místní svalovou vytrvalost.`},"21":{title:`Tréninkový objem`,short:`Tréninkový objem je množství práce, které odvedete. U silového tréninku se obvykle počítá jako počet náročných sérií na svalovou skupinu za týden. Dostatečný objem pohání pokrok, ale série nad rámec toho, co zvládnete zregenerovat, mohou snížit kvalitu tréninku.`},"22":{title:`Intenzita: zátěž a procento 1RM`,short:`Intenzita v silovém tréninku často znamená, jak těžká je zátěž ve srovnání s vaším jednoopakovacím maximem (1RM). Zkušení cvičenci mohou používat procenta k nastavení zátěže. Začátečníci mohou bezpečněji zvolit váhu podle kontrolovaných opakování a úsilí, bez maximálního testu.`},"23":{title:`Hodnocení vnímané námahy (RPE)`,short:`Hodnocení vnímané námahy (RPE) je vaše vlastní hodnocení toho, jak náročné se cvičení zdá. Když si ho zapisujete vedle toho, co jste splnili, poznáte tréninky, které byly lehčí nebo těžší, než se čekalo, a můžete budoucí trénink upravovat po malých krocích.`},"24":{title:`Rezerva opakování (RIR)`,short:`Rezerva opakování (RIR) je váš odhad, kolik dalších čistých opakování byste ještě zvládli před koncem série. Pomáhá vám volit zátěže, které jsou náročné, ale nechávají pár opakování v rezervě, bez testování maxima nebo cvičení do selhání v každé sérii.`},"25":{title:`Tempo zvedání`,short:`Tempo zvedání je rychlost a načasování každé fáze opakování. Kontrolované tempo vám pomáhá cvičit techniku a usnadňuje opakování tréninků. Velmi pomalá opakování nejsou automaticky lepší pro sílu nebo růst svalů.`},"26":{title:`Časované série a výdrže`,short:`Časované série a statické výdrže měří úsilí v sekundách místo v opakováních. Hodí se pro plank, sed u zdi, visy a kondiční intervaly, pokud vaše poloha nebo tempo zůstane po celou dobu stejné.`},"27":{title:`Tréninková frekvence`,short:`Tréninková frekvence je to, jak často v týdnu cvičíte, celkově nebo pro jednu svalovou skupinu. Dobrý rozvrh vám dá dost praxe i práce na pokrok a zároveň zbyde čas na regeneraci a zbytek života.`},"28":{title:`Pořadí cviků v tréninku`,short:`Pořadí cviků rozhoduje o tom, které cviky děláte nejodpočatější. Prioritní cviky, technicky náročné pohyby a zvedání s vysokou silou zařaďte dříve a jednodušší doplňkové, core nebo kondiční cviky přidejte tam, kde slouží cíli tréninku.`},"29":{title:`Trénink do selhání`,short:`Trénink do selhání znamená pokračovat v sérii, dokud nezvládnete další opakování podle zvoleného standardu. Vyžaduje to hodně úsilí, ale pro sílu ani růst svalů to nepotřebujete a přidává to únavu a rizika pro techniku.`},"30":{title:`Plánování délky tréninku`,short:`Plánování délky tréninku znamená odhadnout, jak dlouho opravdu trvá rozcvička, série, odpočinky, střídání cviků a případná kondice. Realistický 20–45minutový trénink, který pokryje vaše hlavní priority, vám často dá víc než delší plán, který se nikdy nevejde do vašeho dne.`},"31":{title:`Základní pohybové vzorce`,short:`Pohybové vzorce seskupují cviky podle toho, co tělo dělá, místo podle jednotlivých svalů. Dřep, předklon v kyčlích, výpad, tlak, tah, nošení, stabilizace středu těla a lokomoce vám dávají praktický způsob, jak vybrat vyvážený soubor cviků.`},"32":{title:`Vzorec dřepu`,short:`Dřep spouští a zvedá vaše tělo současným ohýbáním a natahováním kyčlí, kolen a kotníků. Naučit se dřep, který je pro vaše tělo pohodlný, pomáhá při zvedání, sezení i mnoha silových cvicích na dolní polovinu těla.`},"33":{title:`Vzorec předklonu v kyčlích`,short:`Předklon v kyčlích se ohýbá hlavně v kyčlích, zatímco trup zůstává kontrolovaný. Je základem mrtvých tahů, rumunských mrtvých tahů a pohybů s kettlebellem a trénuje hýždě a zadní stranu stehen, aby vyvíjely sílu.`},"34":{title:`Výpady a trénink jedné nohy`,short:`Výpady, split dřepy a výstupy na stupínek zatěžují jednu nohu víc než druhou a zkoušejí vaši rovnováhu a kontrolu kyčlí. Mohou budovat praktickou sílu dolní poloviny těla a ukázat rozdíly mezi levou a pravou stranou.`},"35":{title:`Horizontální tlaky`,short:`Horizontální tlaky posouvají paže dopředu od trupu, jako u kliků, tlaků na prsa a bench pressu. Trénují hlavně prsa, triceps a přední část ramen a vyžadují kontrolu trupu a ramen.`},"36":{title:`Vertikální tlaky`,short:`Vertikální tlaky tlačí odpor nad hlavu, jako u tlaku jednoručkami na ramena, tlaku činky nad hlavou nebo pike kliku. Trénují sílu ramen a paží a vyžadují, aby lopatky, trup a kyčle spolupracovaly.`},"37":{title:`Horizontální tahy`,short:`Horizontální tahy přitahují ruce nebo lokty k trupu, jako u veslování. Veslování trénuje horní část zad, široké svaly zádové, zadní část ramen a ohýbače loktů a vyvažuje mnoho tlakových cviků.`},"38":{title:`Vertikální tahy`,short:`Vertikální tahy přitahují lokty dolů z polohy nad hlavou, jako u shybů, shybů podhmatem a stahování kladky. Zapojují hlavně široké svaly zádové a horní část zad s výraznou pomocí paží a trupu.`},"39":{title:`Trénink středu těla: proti prohnutí, proti rotaci, proti úklonu`,short:`Síla středu těla zahrnuje i odolávání nežádoucímu pohybu, nejen ohýbání trupu. Cviky proti prohnutí, proti rotaci a proti úklonu učí váš trup zůstat kontrolovaný, i když na něj působí síly.`},"40":{title:`Nošení zátěže`,short:`Nošení zátěže znamená chůzi s váhou v rukou, například s jednoručkami nebo kettlebelly. Nošení je jednoduché, ale náročné: trénuje sílu úchopu, stabilitu trupu, držení těla a vzorec chůze dohromady.`},"41":{title:`Izolované cviky`,short:`Izolované cviky se soustředí na pohyb v jednom hlavním kloubu, například bicepsový zdvih nebo extenze nohou. Umožňují dát svalu navíc praxi nebo tréninkový objem nad rámec toho, co už získává z vícekloubových pohybů.`},"42":{title:`Vyvážení tlaků a tahů`,short:`Tlakové a tahové pohyby trénují různé, ale překrývající se části horní poloviny těla. Když děláte obojí, budujete všestrannou sílu a zabráníte tomu, aby se váš program zaplnil tlakovými cviky.`},"43":{title:`Zásady tréninku`,short:`Dobrý trénink se řídí několika propojenými zásadami: specifičností, progresivním přetížením, individualizací, regenerací, pravidelností a zvratností. Jsou spolehlivějším vodítkem než kopírování rutiny pokročilého sportovce.`},"44":{title:`Progresivní přetížení`,short:`Progresivní přetížení znamená pomalu ztěžovat cvik, jak se vaše tělo přizpůsobuje. Potřebujete ho, abyste se dál zlepšovali, a můžete ho uplatnit prostřednictvím opakování, odporu, kontroly pohybu, rozsahu pohybu nebo těžšího cviku, nejen těžších vah.`},"45":{title:`Dvojitá progrese`,short:`Dvojitá progrese je jednoduchý způsob postupu v silovém tréninku: přidáváte opakování ve zvoleném rozsahu a poté přidáte váhu. Odstraní většinu dohadů při výběru nové zátěže.`},"46":{title:`Celotělové, horní/dolní a dělené programy`,short:`Tréninkový split je způsob, jak rozložit cviky během týdne. Celotělové, horní/dolní a dělené podle svalových skupin mohou všechny budovat sílu a svaly, pokud celková práce, úsilí a regenerace vyhovují vám.`},"47":{title:`Sestavení tréninkového týdne`,short:`Tréninkový týden uspořádává náročné tréninky, lehčí aktivitu a regeneraci tak, aby plán odpovídal vašemu skutečnému životu. Dobrý rozvrh vás udrží v tréninku dostatečně často, aniž by se hromadila únava z náročných tréninků za sebou.`},"48":{title:`Základy periodizace`,short:`Periodizace znamená plánovat, jak se tréninková zátěž mění v čase. Lineární, vlnový a blokový přístup jsou způsoby, jak organizovat pokrok, ale začátečníci se často zlepší s mnohem jednodušším programem, kterého se drží.`},"49":{title:`Odlehčovací týdny`,short:`Odlehčení je krátké období lehčího tréninku, které nechá únavu opadnout, zatímco dál cvičíte pohyby. Odlehčení můžete naplánovat dopředu nebo ho využít, když vaše běžná zátěž přestane být něčím, co zvládáte zregenerovat.`},"50":{title:`Výběr cviků`,short:`Vybírejte cviky, které odpovídají vašemu cíli, tréninkové úrovni, vybavení, prostoru a případným omezením. Nejlepší cvik je ten, který zvládnete bezpečně, pravidelně opakovat a pomalu ztěžovat.`},"51":{title:`Progrese a regrese`,short:`Progrese cvik ztěžuje a regrese ho usnadňuje. Obojí jsou běžné trenérské nástroje pro přizpůsobení cviku vaší síle, technice a regeneraci.`},"52":{title:`Superserie a obvody`,short:`Superserie spojuje cviky s malým odpočinkem mezi nimi a obvod střídá několik pohybů. Obojí může ušetřit čas, ale únava a kratší regenerace mohou snížit kvalitu těžkých nebo velmi technických cviků.`},"53":{title:`Tréninkové plató`,short:`Tréninkové plató je období, kdy se schopnost přestane zlepšovat, i když dál cvičíte. Plató jsou běžná a příčinou může být regenerace, příliš malá zátěž, nekonzistentní měření nebo pomalejší pokrok, který přichází se zkušenostmi.`},"54":{title:`Ztráta kondice a návrat po pauze`,short:`Ztráta kondice je částečná ztráta formy po omezení nebo ukončení tréninku. Opatrný návrat obnovuje vaši kapacitu krok za krokem, bez očekávání, že vaše tělo hned zvládne dřívější zátěž.`},"55":{title:`Trénink s vlastní vahou`,short:`Trénink s vlastní vahou využívá vaše tělo jako odpor pro sílu a nácvik pohybu. Dřepy, kliky, výpady, plank a shyby vás mohou dovést velmi daleko bez nákupu celé sady závaží.`},"56":{title:`Trénink s jednoručkami`,short:`Jednoručky jsou univerzální volné váhy pro tlaky, veslování, dřepy, předklony v kyčlích a cviky na jednu nohu. Každá paže se pohybuje samostatně a můžete měnit úchop, ale musíte dávat pozor na rovnováhu, manipulaci a uložení.`},"57":{title:`Trénink s kettlebellem`,short:`Kettlebell je závaží s držadlem a hmotou posunutou mimo úchop. Můžete ho použít pro kontrolované silové cviky i pro rychlejší pohyby, jako jsou švihy, ale technicky náročnější cviky vyžadují cílený nácvik.`},"58":{title:`Trénink s odporovými gumami`,short:`Odporové gumy poskytují přenosný odpor, který se obvykle zvyšuje s natažením gumy. Můžete je použít pro tlaky, veslování, tahy a doplňkové cviky, pokud je bezpečně ukotvíte a udržujete v dobrém stavu.`},"59":{title:`Trénink s činkou`,short:`Činka umožňuje postupně zvyšovat zátěž u zdvihů, jako jsou dřepy, mrtvé tahy, tlaky a veslování. Je vhodná pro budování vysoké úrovně síly, ale potřebujete správnou techniku, správné nastavení vybavení a bezpečnostní opatření.`},"60":{title:`Posilovací stroje a kladky`,short:`Posilovací stroje a kladkové stanice nabízejí nastavitelný odpor a mohou zjednodušit přípravu cviku. Jsou účinnými nástroji silového tréninku vedle volných vah, ne horší náhradou.`},"61":{title:`Hrazda: instalace a bezpečnost`,short:`Hrazda umožňuje shyby, shyby podhmatem a cviky ve visu, ale jen pokud je bezpečně nainstalovaná a dimenzovaná pro způsob, jakým ji používáte. Na kvalitě upevnění záleží víc než na tom, kolik opakování zvládnete.`},"62":{title:`Lavice, stupínky a švihadla`,short:`Lavice, stupínky a švihadla přidávají mnoho cviků doma i v posilovně. Každé z nich funguje dobře jen tehdy, když jeho velikost, stabilita a volný prostor odpovídají pohybu a člověku, který ho používá.`},"63":{title:`Volba správné zátěže`,short:`Správná zátěž je dost těžká na to, aby vás nutila pracovat, a dost lehká, aby každé opakování zůstalo kontrolované. Jako začátečník můžete volit váhy podle toho, jak dobře se pohybujete a kolik opakování vám zbývá, bez testování maximálního zdvihu.`},"64":{title:`Trénink s domácími náhradami`,short:`Domácí předměty mohou někdy nahradit tréninkové vybavení jako lehký odpor nebo opora. Použijte je až poté, co zkontrolujete jejich stabilitu, kolik zátěže unesou, úchop a to, co s nimi plánujete dělat.`},"65":{title:`Použitelný prostor a volný prostor kolem cviku`,short:`Použitelný tréninkový prostor zahrnuje nejen místo, kde stojíte, ale i vše, kudy se vaše tělo a vybavení při každém opakování pohybují. Jeho změření vám pomůže vyhnout se nárazům a umožní TrainUp vybrat cviky, které se opravdu vejdou.`},"66":{title:`Výška stropu a cviky nad hlavou`,short:`Výška stropu rozhoduje o tom, zda jsou praktické tlaky nad hlavu, shyby, skoky a skákání přes švihadlo. Pohyb se může vejít, když stojíte na místě, a stát se nebezpečným, jakmile se paže, zátěž nebo tělo pohybují vzhůru.`},"67":{title:`Tréninkový povrch a obuv`,short:`Vaše podlaha a obuv ovlivňují stabilitu, přilnavost a to, jak náročný je každý dopad. Nejlepší kombinace závisí na tom, zda jde hlavně o zvedání, běh, skákání nebo pomalou mobilitu.`},"68":{title:`Hluk a nárazy při cvičení doma`,short:`Domácí tréninky mohou rušit sousedy a bouchat do podlahy, hlavně skoky a odhazování závaží. Cviky s nižším nárazem vám stále dají skutečnou kondici s mnohem menším hlukem.`},"69":{title:`Trénink v posilovně: etiketa a bezpečnost`,short:`Bezpečný trénink v posilovně znamená dobrou techniku a ohleduplnost ke sdílenému vybavení a lidem kolem vás. Jasná etiketa snižuje riziko zranění a usnadňuje používání vybavení všem, když je plno.`},"70":{title:`Trénink venku: počasí a terén`,short:`Venku se počasí, povrch, světlo i vybavení mění ze dne na den. Úprava toho, jak tvrdě a kam jdete, dělá procházky, běhy a tréninky v parku bezpečnější a snáze udržitelné.`},"71":{title:`Budování aerobního základu`,short:`Aerobní základ je vaše schopnost udržet dlouho poměrně pohodlnou aktivitu. Jeho budování usnadňuje zvládání každodenního pohybu i náročnějších kondičních tréninků.`},"72":{title:`Kardio ve stabilním tempu`,short:`Kardio ve stabilním tempu udržuje vaše úsilí po celý trénink poměrně vyrovnané, například při chůzi, pomalém běhu, jízdě na kole nebo na kardio strojích. Buduje vytrvalost bez opakovaných intervalů naplno.`},"73":{title:`Intervalový trénink`,short:`Intervalový trénink střídá náročnější práci s lehčí regenerací. Nastavením délky a náročnosti každé části můžete krok za krokem zlepšovat kondici a žádný trénink nemusí být zkouškou naplno.`},"74":{title:`HIIT a Tabata`,short:`Vysoce intenzivní intervalový trénink (HIIT) střídá skutečně náročné výkony s regenerací a Tabata je jeden konkrétní formát s 20 sekundami práce a 10 sekundami odpočinku. Žádný z pojmů neznamená jen jakýkoli rychlý trénink.`},"75":{title:`Poměry práce a odpočinku`,short:`Poměr práce a odpočinku srovnává, jak dlouho pracujete a jak dlouho regenerujete. Poměry jako 1:3, 1:1 a 2:1 určují, jak nabitý se trénink cítí, a jejich účinek závisí také na tom, jak náročný je pracovní interval.`},"76":{title:`Kondice s nízkým nárazem`,short:`Kondice s nízkým nárazem zvyšuje dech a tepovou frekvenci s méně tvrdými dopady. Hodí se pro začátečníky, lidi, kteří musí omezit nárazy, a každého, kdo cvičí tam, kde je problém hluk.`},"77":{title:`Plyometrie a skákání`,short:`Plyometrie trénuje výbušný pohyb rychlým protažením a zkrácením svalů, obvykle pomocí poskoků, skoků a odrazů. Vyžaduje kontrolované dopady, postupné budování a dost odpočinku, aby zůstalo každé opakování svižné.`},"78":{title:`Základy techniky běhu`,short:`Technika běhu se týká držení těla, načasování kroku a postupného zvykání na opakované nárazy. Jako začátečník získáte víc z pohodlného, opakovatelného běhu a postupného budování než z kopírování jednoho „dokonalého“ došlapu.`},"79":{title:`Dovednosti se švihadlem`,short:`Švihadlo je přenosná kondice, která vyžaduje načasování švihu a malé, opakované poskoky. Správnou délku švihadla, kontrolu zápěstí a rytmus dopadů si ujasněte dříve, než zkusíte dlouhé nebo rychlé intervaly.`},"80":{title:`Kombinace síly a kardia`,short:`Odporový trénink i kardio společně budují svalovou i kardiovaskulární kondici. Pro většinu rekreačních cvičenců rozumný týdenní rozvrh umožní zlepšovat se v obojím, takže nemusíte vybírat jedno.`},"81":{title:`Rozcvička`,short:`Rozcvička připraví váš dech, oběh, klouby, svaly a koordinaci na nadcházející práci. Krátká obecná rozcvička následovaná nácvikem cviku, který se chystáte dělat, obvykle pomůže víc než pevně daná sada protažení.`},"82":{title:`Zklidnění po cvičení`,short:`Zklidnění vás po náročné aktivitě pomalu vrací k odpočinku lehkým pohybem a klidným dýcháním. Může být příjemné a snadno se zařadí, ale neexistuje dobrý důkaz, že zabraňuje opožděné svalové bolesti.`},"83":{title:`Mobilita a pohyblivost`,short:`Pohyblivost je rozsah, kterým se kloub dokáže pohybovat, a mobilita je vaše schopnost tento rozsah sami ovládat. Při výběru cviků má větší váhu rozsah, který dokážete použít s kontrolou, než nejhlubší poloha, které dosáhnete.`},"84":{title:`Statické a dynamické protahování`,short:`Statické protahování drží polohu a dynamické protahování se pohybuje v rozsahu pod kontrolou. Obojí vám může pomoci připravit se na pohyb nebo zlepšit pohyblivost, pokud je přizpůsobíte svému cíli a udržíte pohodlnou intenzitu.`},"85":{title:`Mobilita kyčlí`,short:`Mobilita kyčlí je pohodlný pohyb v kyčelních kloubech: ohýbání, natahování, rotace a pohyb nohy do strany. Pomáhá vám dosáhnout užitečných poloh při dřepu, předklonu a výpadu, i když anatomie kyčlí a pohodlné rozsahy se u každého liší.`},"86":{title:`Mobilita hrudní páteře a ramen`,short:`Vaše hrudní páteř a ramena se podílejí na dosahování, rotaci, tlacích nad hlavu a mnoha tahových pohybech. Mobilitní cvičení může tyto pohyby usnadnit, pokud zároveň budujete sílu a kontrolu k jejich využití.`},"87":{title:`Regenerace mezi tréninky`,short:`Mezi tréninky únava odeznívá a vaše tělo se přizpůsobuje tréninku. Dobrý plán střídá náročné tréninky s dostatkem odpočinku nebo lehčí aktivity, abyste mohli podávat výkon týden co týden.`},"88":{title:`Spánek a trénink`,short:`Spánek podporuje fyzickou regeneraci, učení, náladu a stabilní tréninkový výkon. Dospělí obecně potřebují alespoň sedm hodin za noc a mnozí se cítí nejlépe při zhruba sedmi až devíti hodinách kvalitního spánku.`},"89":{title:`Opožděná svalová bolest`,short:`Opožděná svalová bolest (DOMS) je dočasná citlivost a ztuhlost, která často následuje po novém nebo neobvykle náročném tréninku. Rozvíjí se po cvičení a často bývá nejhorší zhruba po 24–72 hodinách.`},"90":{title:`Přetížení a přetrénování`,short:`Přetížení je dočasný pokles výkonu poté, co nahromadíte víc tréninkové zátěže, než vaše tělo právě zvládá zregenerovat. Skutečný syndrom přetrénování je závažnější a trvá déle a jeden špatný trénink neprokazuje, že ho máte.`},"91":{title:`Hydratace`,short:`Dostatečný příjem tekutin podporuje oběh, regulaci teploty a výkon při cvičení. Kolik musíte pít, závisí na tom, kolik se potíte, na počasí a délce tréninku a nadměrné pití vody může být také nebezpečné.`},"92":{title:`Základy výživy pro aktivní lidi`,short:`Trénink jde lépe, když jíte dostatek jídla, pestrou škálu živin a dost bílkovin pro obnovu a adaptaci. TrainUp učí obecné zásady výživy a nedává jídelníčky, kalorické cíle ani léčebné diety.`},"93":{title:`Denní připravenost a stres`,short:`Připravenost je to, jak jste připraveni a jak dobře podáváte výkon na začátku tréninku. Špatný spánek, nemoc a životní stres mohou změnit, kolik tréninku je pro vás ten den správné, i když psaný plán zůstává stejný.`},"94":{title:`Aktivní regenerace`,short:`Aktivní regenerace je lehký pohyb mezi náročnějšími tréninky. Chůze, pomalá jízda na kole a jemná mobilita vás udrží v pohybu, aniž by přidaly druhý náročný trénink.`},"95":{title:`Technika před zátěží`,short:`Dobrá technika dělá pohyb opakovatelným a kontrolovaným dříve, než přidáte odpor. Zátěž zvyšujte, jen když dokážete udržet své polohy, rozsah pohybu a jistotu.`},"96":{title:`Bolest nebo nepohodlí: jak je rozlišit`,short:`Cvičení často přináší svalové úsilí, únavu a krátkodobou bolestivost, ale bolest, která je ostrá, zhoršuje se nebo je doprovázena nervovými příznaky, vyžaduje pozornost. Jednoduchá kontrola příznaků vám pomůže zvolit bezpečnější další krok, aniž byste se pokoušeli něco diagnostikovat.`},"97":{title:`Varovné příznaky: kdy okamžitě přestat`,short:`Některé příznaky při cvičení mohou signalizovat naléhavý zdravotní problém místo běžné únavy. Jejich rozpoznání je důležitější než dokončení tréninku nebo splnění plánovaného cíle.`},"98":{title:`Axiální zatížení páteře`,short:`Axiální zatížení páteře je tlaková síla, která působí podél vaší páteře při pohybu nebo silovém tréninku. Když o něm víte, pochopíte, proč některé cviky nemusí být vhodné, pokud chcete možnosti, které páteř zatěžují méně.`},"99":{title:`Trénink s citlivými koleny`,short:`Citlivá kolena mohou způsobit, že některé pohyby, hloubky nebo úrovně nárazu jsou nepříjemné. Rozumná tréninková rozhodnutí mohou omezit zbytečné vzplanutí potíží, ale potíže s koleny, které přetrvávají nebo jsou silné, vyžadují odborné vyšetření.`},"100":{title:`Trénink s citlivými zády`,short:`Citlivá spodní část zad může ovlivnit, jaké zátěže, rozsahy a polohy při cvičení snášíte. Plánování obecné kondice může upřednostňovat pohodlné varianty a postupný pokrok, ale nenahrazuje klinické vyšetření ani rehabilitaci.`},"101":{title:`Trénink s citlivými rameny`,short:`To, jak se rameno cítí, může záviset na úhlu tlaku, úchopu, rozsahu pohybu a zátěži. Výběr variant, které snášíte, vám pomáhá zůstat aktivní, ale bolest ramene bez jasné příčiny nebo bolest, která přetrvává, vyžaduje odborné vyšetření.`},"102":{title:`Trénink s citlivými zápěstími`,short:`Zápěstí vás mohou bolet, když ruce nesou váhu těla nebo drží zátěž v nevhodném úhlu. Změna úchopu, opory nebo cviku může někdy zátěž zmírnit, zatímco dál trénujete stejný pohybový vzorec.`},"103":{title:`Náročnost koordinace a bezpečná volba cviků`,short:`Náročnost koordinace je to, kolik rovnováhy, načasování a kontroly pohybu cvik od vás vyžaduje. Přizpůsobení vašim zkušenostem a únavě vám umožní procvičit správnou techniku dříve, než přidáte rychlost nebo zátěž.`},"104":{title:`Jištění a bezpečné odhození`,short:`Jištění znamená, že vám někdo pomůže, když nedokážete bezpečně dokončit opakování. Ať cvičíte s partnerem, nebo sami, správně nastavte stojan, zvolte váhu, kterou zvládnete ovládat, a vězte, co uděláte, když se zdvih nepodaří.`},"105":{title:`Začínáme od nuly`,short:`Jako začátečník můžete zlepšit kondici malou rutinou, kterou zvládnete opakovat. V prvním měsíci se zaměřte na učení pohybů, pohodlné úsilí a pravidelné cvičení a zvedání co nejvyšší váhy nechte na později.`},"106":{title:`Trénink po padesátce`,short:`I po padesátce můžete budovat sílu a kondici a pravidelné cvičení vám pomáhá zůstat pohyblivými a nezávislými. Plán stavte na svém zdraví, tréninkové historii, rovnováze a regeneraci. Být starší padesáti let neznamená, že potřebujete stejnou lehkou rutinu jako všichni vrstevníci.`},"107":{title:`Silový trénink pro teenagery`,short:`Vedený silový trénink navržený pro váš věk vám může pomoci budovat koordinaci, sílu a jistotu v pohybu. Na prvním místě je dobrá technika a postupný pokrok a kopírování maximálního zvedacího programu dospělého je špatný vzor.`},"108":{title:`Cvičení během těhotenství a po porodu`,short:`Pohybová aktivita často pomáhá při nekomplikovaném těhotenství i po porodu, ale to, co vaše tělo potřebuje, se v těchto obdobích může hodně měnit. Individuální radu získejte od svého porodnického týmu, zejména pokud máte příznaky nebo zdravotní komplikace.`},"109":{title:`Začátek cvičení s nadváhou`,short:`Lidé každé velikosti těla mohou díky správnému druhu aktivity zesílit, zlepšit kondici a zdraví. Dobrý začátek se zaměřuje na pohodlí, nižší nárazy a schopnost zvládnout víc a tělesná hmotnost je jen jedním z několika způsobů, jak měřit úspěch.`},"110":{title:`Krátké tréninky pro plné diáře`,short:`Dobře naplánovaný 10–20minutový trénink může vybudovat tréninkový návyk a zlepšit vaši kondici. Pokud jste zaneprázdnění, krátké tréninky, které děláte často, obvykle fungují lépe než ambiciózní plán, který nedokážete dodržet.`},"111":{title:`Vedení tréninkového deníku`,short:`Tréninkový deník zaznamenává, co jste plánovali, co jste udělali a jak jste se cítili. Pravidelné vedení vám pomáhá odlišit skutečný pokrok od běžných denních výkyvů a dává vám lepší informace, když měníte program.`},"112":{title:`Měření pokroku v síle`,short:`Pokrok v síle se může projevit více opakováními, těžšími zátěžemi nebo obtížnějšími variantami cviku. Spravedlivé srovnání udržuje stejnou techniku a podmínky a osobní rekord je jen jedním z čísel, která se počítají.`},"113":{title:`Měření pokroku v kondici`,short:`Vaše kondice se zlepšuje, když dokážete pokračovat déle, překonat vzdálenost rychleji nebo zvládnout stejný úkol s menším úsilím. Opakování jednoduchých testů za podobných podmínek usnadňuje čtení trendů vytrvalosti.`},"114":{title:`Trendy tělesné hmotnosti a míry`,short:`Tělesná hmotnost a tělesné míry se mění i z jiných důvodů než přibývání nebo ztráta tuku, například kvůli tekutinám a trávení. Pokud se rozhodnete je sledovat, trendy v čase vám řeknou víc než jednotlivé hodnoty.`},"115":{title:`Jednoduché testy kondice`,short:`Jednoduché praktické testy dávají rychlý obraz vaší silové vytrvalosti, rovnováhy nebo kondice. Nejvíce se hodí, když stejný test opakujete stejným způsobem, a srovnání s jedním skóre určeným pro všechny vám říká mnohem méně.`},"116":{title:`Úprava plánu na základě zpětné vazby`,short:`Váš plán funguje nejlépe, když další kroky utváří to, co jste splnili a jak se vám to dělalo. Malé, opatrné změny zlepšují přizpůsobení. Měňte jednu věc najednou a trénink, který právě děláte, nechte tak, jak je.`},"117":{title:`Mýtus: tuk lze spalovat z jedné části těla`,short:`Trénink břicha vám nedovolí spolehlivě si vybrat, kde tělo ztratí tuk. Cílené cviky posilují svaly, které trénujete, zatímco to, kde tuk sídlí a jak se mění, závisí na širších biologických a behaviorálních faktorech.`},"118":{title:`Mýtus: silový trénink dělá z žen objemné postavy`,short:`Odporový trénink automaticky nedělá z žen velmi svalnaté postavy. Obvyklým výsledkem je víc síly a lepší funkce svalů a to, kolik viditelného svalstva získáte, závisí na tréninku, čase, výživě a vaší vlastní biologii.`},"119":{title:`Mýtus: kardio ničí svalové zisky`,short:`Aerobní cvičení a odporový trénink mohou v jednom kondičním programu spolupracovat. Některé kombinace mohou mírně snížit určité přírůstky síly nebo výbušnosti, ale kardio automaticky nezruší růst svalů.`},"120":{title:`Mýtus: bez bolesti žádný pokrok`,short:`Úsilí a postupně náročnější trénink budují kondici, ale ke zlepšení nepotřebujete bolest ani silnou svalovou bolest. Usilujte o výzvu, kterou dokážete ovládat, dobrou techniku a regeneraci a neměřte úspěch tím, kolik trpíte.`}};var i={ui:n,topics:t,theories:a};export{i as default,a as theories,t as topics,n as ui};